from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th positive amount that is a multiple of a coin.

    Amounts are counted once even when they are multiples of multiple
    denominations. Inclusion-exclusion counts the union of those multiples,
    and a binary search locates the requested amount.
    """
    # A denomination that is a multiple of another contributes no new amounts.
    denominations = sorted(set(coins))
    denominations = [
        coin
        for coin in denominations
        if not any(coin != other and coin % other == 0 for other in denominations)
    ]

    upper = min(denominations) * k

    # Map each subset LCM to its combined inclusion-exclusion coefficient.
    # Combining equal LCMs keeps counting inexpensive even when many subsets
    # describe the same multiples. LCMs above upper cannot affect the search.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for subset_lcm, coefficient in coefficients.items():
            combined_lcm = lcm(subset_lcm, coin)
            if combined_lcm <= upper:
                additions[combined_lcm] = additions.get(combined_lcm, 0) - coefficient
        for subset_lcm, coefficient in additions.items():
            updated = coefficients.get(subset_lcm, 0) + coefficient
            if updated:
                coefficients[subset_lcm] = updated
            else:
                coefficients.pop(subset_lcm, None)

    def count_at_most(amount: int) -> int:
        return sum(coefficient * (amount // divisor) for divisor, coefficient in coefficients.items())

    low = 1
    high = upper
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low
